-- ProxiWork schema and least-privilege access controls.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, first_name text not null default '', last_name text not null default '', phone text, suburb text, state text, postcode text, latitude double precision, longitude double precision, resume_path text, preferred_distance_km integer not null default 20 check(preferred_distance_km between 5 and 50), weekly_application_goal integer not null default 1 check(weekly_application_goal > 0), onboarding_completed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.skills (id uuid primary key default gen_random_uuid(), name text not null, normalised_name text not null unique, created_at timestamptz not null default now());
create table public.profile_skills (profile_id uuid references public.profiles(id) on delete cascade, skill_id uuid references public.skills(id) on delete cascade, proficiency text, created_at timestamptz not null default now(), primary key(profile_id,skill_id));
create table public.work_experience (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, company_name text not null, position_title text not null, start_date date not null, end_date date, is_current boolean not null default false, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(end_date is null or end_date >= start_date));
create table public.education (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, certification_level text not null, course_name text not null, institution text not null, start_date date, end_date date, is_currently_studying boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(end_date is null or start_date is null or end_date >= start_date));
create table public.employers (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null references auth.users(id), company_name text not null, description text not null default '', website text, suburb text not null, state text not null, postcode text not null, verification_status text not null default 'pending' check(verification_status in ('pending','verified','rejected')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.jobs (id uuid primary key default gen_random_uuid(), employer_id uuid not null references public.employers(id) on delete cascade, title text not null, description text not null, responsibilities text, requirements text, employment_type text not null check(employment_type in ('casual','part_time','full_time','contract')), suburb text not null, state text not null, postcode text not null, latitude double precision, longitude double precision, status text not null default 'draft' check(status in ('draft','published','closed')), application_deadline timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.job_skills (job_id uuid references public.jobs(id) on delete cascade, skill_id uuid references public.skills(id) on delete cascade, primary key(job_id,skill_id));
create table public.saved_jobs (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, job_id uuid not null references public.jobs(id) on delete cascade, action text not null check(action in ('saved','dismissed')), created_at timestamptz not null default now(), unique(user_id,job_id));
create table public.applications (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs(id) on delete cascade, applicant_id uuid not null default auth.uid() references auth.users(id) on delete cascade, resume_path text, cover_letter text, status text not null default 'submitted' check(status in ('submitted','reviewing','shortlisted','rejected','withdrawn','accepted')), applied_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(applicant_id,job_id));
create table public.job_preferences (id uuid primary key default gen_random_uuid(), user_id uuid not null unique default auth.uid() references auth.users(id) on delete cascade, employment_types text[] not null default '{}', preferred_distance_km integer not null default 20 check(preferred_distance_km between 5 and 50), preferred_suburb text, preferred_state text, weekly_application_goal integer not null default 1 check(weekly_application_goal > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index jobs_search_idx on public.jobs(status,employment_type,state,suburb); create index applications_applicant_idx on public.applications(applicant_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,first_name,last_name) values(new.id,coalesce(new.raw_user_meta_data->>'first_name',''),coalesce(new.raw_user_meta_data->>'last_name','')) on conflict(id) do nothing; return new; end; $$; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.skills enable row level security; alter table public.profile_skills enable row level security; alter table public.work_experience enable row level security; alter table public.education enable row level security; alter table public.employers enable row level security; alter table public.jobs enable row level security; alter table public.job_skills enable row level security; alter table public.saved_jobs enable row level security; alter table public.applications enable row level security; alter table public.job_preferences enable row level security;
create policy "own_profile" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid()); create policy "skills_read" on public.skills for select using(true); create policy "own_profile_skills" on public.profile_skills for all using(profile_id=auth.uid()) with check(profile_id=auth.uid()); create policy "own_experience" on public.work_experience for all using(profile_id=auth.uid()) with check(profile_id=auth.uid()); create policy "own_education" on public.education for all using(profile_id=auth.uid()) with check(profile_id=auth.uid()); create policy "published_jobs" on public.jobs for select using(status='published' or exists(select 1 from public.employers e where e.id=employer_id and e.owner_user_id=auth.uid())); create policy "own_employers" on public.employers for all using(owner_user_id=auth.uid()) with check(owner_user_id=auth.uid() and verification_status='pending'); create policy "own_jobs" on public.jobs for all using(exists(select 1 from public.employers e where e.id=employer_id and e.owner_user_id=auth.uid())) with check(exists(select 1 from public.employers e where e.id=employer_id and e.owner_user_id=auth.uid())); create policy "own_saved_jobs" on public.saved_jobs for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "read_applications" on public.applications for select using(applicant_id=auth.uid() or exists(select 1 from public.jobs j join public.employers e on e.id=j.employer_id where j.id=job_id and e.owner_user_id=auth.uid())); create policy "insert_own_application" on public.applications for insert with check(applicant_id=auth.uid()); create policy "withdraw_own_application" on public.applications for update using(applicant_id=auth.uid()) with check(applicant_id=auth.uid() and status='withdrawn'); create policy "own_preferences" on public.job_preferences for all using(user_id=auth.uid()) with check(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('cvs','cvs',false,5242880,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict(id) do nothing; create policy "own_cv_read" on storage.objects for select to authenticated using(bucket_id='cvs' and (storage.foldername(name))[1]=auth.uid()::text); create policy "own_cv_insert" on storage.objects for insert to authenticated with check(bucket_id='cvs' and (storage.foldername(name))[1]=auth.uid()::text); create policy "own_cv_delete" on storage.objects for delete to authenticated using(bucket_id='cvs' and (storage.foldername(name))[1]=auth.uid()::text);
